import{_ as r,o as p,c as t,a2 as a}from"./chunks/framework.CAKCj7G0.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"服务器相关/debian.md","filePath":"服务器相关/debian.md"}'),l={name:"服务器相关/debian.md"};function i(n,e,b,s,c,o){return p(),t("div",null,[...e[0]||(e[0]=[a('<p>一， -y 自动执行安装</p><p>二， package 包名/软件名，以下命令中凡是出现package需要自行替换。</p><p>三， apt-get 无效时可更换为 apt 反之同理。</p><p>四，某些情况下可以不用输入 sudo</p><p>1.更新源</p><p>sudo apt-get update -y<br> 2.更新已安装的包</p><p>sudo apt-get upgrade -y<br> 3.升级系统</p><p>sudo apt-get dist-upgrade -y<br> 4.使用 dselect 升级</p><p>sudo apt-get dselect-upgrade -y<br> 5.了解使用依赖</p><p>sudo apt-cache depends package<br> 6.查看该包被哪些包依赖</p><p>sudo apt-cache rdepends package<br> 7.安装相关的编译环境</p><p>sudo apt-get build-dep package<br> 8.下载该包的源代码</p><p>sudo apt-get source package<br> 9.清理无用的包</p><p>sudo apt-get clean &amp;&amp; sudo apt-get autoclean<br> 10.检查是否有损坏的依赖</p><p>sudo apt-get check<br> 11.清理所有软件缓存（即缓存在/var/cache/apt/archives目录里的deb包）</p><p>sudo apt-get clean<br> 12.搜索包</p><p>sudo apt-cache search package<br> 13.获取包的相关信息，如说明、大小、版本等</p><p>sudo apt-cache show package<br> 14.安装包</p><p>sudo apt-get install package<br> 15.重新安装包</p><p>sudo apt-get install package - - reinstall<br> 16.修复安装”-f = –fix-missing”</p><p>sudo apt-get -f install<br> 17.删除包</p><p>sudo apt-get remove package<br> 18.删除包，包括删除配置文件等</p><p>sudo apt-get remove package - - purge<br> 19.安装wget下载工具</p><p>sudo apt-get install wget -y<br> 20.<a href="https://so.csdn.net/so/search?q=%E5%AE%89%E8%A3%85git&amp;spm=1001.2101.3001.7020" target="_blank" rel="noreferrer">安装git</a></p><p>sudo apt-get install git -y<br> 21.安装curl</p><p>sudo apt-get install curl -y<br> 22.<a href="https://so.csdn.net/so/search?q=%E5%AE%89%E8%A3%85Nginx&amp;spm=1001.2101.3001.7020" target="_blank" rel="noreferrer">安装Nginx</a></p><p>apt-get install nginx</p><p>#输入以下命令查看是否可以正常访问, 顺便验证下安装是否成功.<br> curl -I 127.0.0.1</p><p>#若输出类似如下内容, 那么说明安装没问题咯.<br> HTTP/1.1 200 OK<br> Server: nginx/1.10.3<br> Date: <a href="https://so.csdn.net/so/search?q=Sat&amp;spm=1001.2101.3001.7020" target="_blank" rel="noreferrer">Sat</a>, 14 Mar 2020 05:36:45 GMT<br> Content-Type: text/html<br> Content-Length: 612 Last-Modified: Sat, 14 Mar 2020 05:36:27 GMT<br> Connection: keep-alive<br> ETag: “5e6c6d5b-264”<br> Accept-Ranges: bytes<br> 　　Nginx绑定域名</p><p>22.1配置文件/etc/nginx/conf.d/**.conf</p><p>22.2为每一个域名建立一个单独的配置文件时输入以下内容：</p><p>server<br> {<br> listen 80; #监听端口设为 80。<br> server_name blog.tgae.xyz; #绑定您的域名。<br> index index.htm index.html index.php; #指定默认文件。<br> root /var/www/html/hlzspace; #指定网站根目录。<br> include location.conf; #当您需要调用其他配置文件时才粘贴此项，如无需要，请删除此项。<br> }<br> 　　22.3将多个域名规则写进一个共同的配置文件时输入以下内容：</p><p>server<br> {<br> listen 80; #监听端口设为 80。<br> server_name blog.tgae.xyz; #绑定您的域名。<br> index index.htm index.html index.php; #指定默认文件。<br> root /var/www/html/hlzspace; #指定网站根目录。<br> include location.conf; #当您需要调用其他配置文件时才粘贴此项，如无需要，请删除此项。<br> }<br> server<br> {<br> listen 80; #监听端口设为 80。<br> server_name blog.tgae.xyz; #绑定您的域名。<br> index index.htm index.html index.php; #指定默认文件。<br> root /var/www/html/hlz2space; #指定网站根目录。<br> include location.conf; #当您需要调用其他配置文件时才粘贴此项，如无需要，请删除此项。<br> }<br> 　　22.4为无 WWW 前缀的域名配置规则并加 301 跳转时输入以下内容：</p><p>server<br> {<br> listen 80;<br> server_name tgae.xyz;<br> rewrite ^/(.*) <a href="http://www.tgae.xyz/$1" target="_blank" rel="noreferrer">http://www.tgae.xyz/$1</a> permanent;<br> }<br> 　　22.5需要为域名添加 404 提示时输入以下内容：</p><p>server<br> {<br> listen 80; #监听端口设为 80。<br> server_name blog.tgae.xyz; #绑定您的域名。<br> index index.htm index.html index.php; #指定默认文件。<br> root /var/www/html/hlzspace; #指定网站根目录。<br> include location.conf; #当您需要调用其他配置文件时才粘贴此项，如无需要，请删除此项。<br> error_page 404 #/404.html;<br> }<br> 　　22.6重启nginx</p><p>$ service nginx restart<br> 23.安装screen</p><p>sudo apt-get install screen -y<br> #使用方法，使用时注意(space)空格<br> screen -S 创建新窗口例：screen -S lnmp<br> screen -ls 列出所有窗口，直接输入。<br> screen -r 恢复窗口例：screen -r lnmp 或者是 通过-ls命令获取的窗口前数字列：screen -r 1234</p><p>#There is no screen to be resumed matching<br> #解决方法：<br> screen -D -r 18352<br> #解释：-D -r 先删除前一用户再登陆。</p><p>24.安装Firewalld<br> UFW、firewall、iptables防火墙配置 常见的linux系统防火墙有：UFW、firewall、iptables，其中，UFW是Debian系列的默认防火墙，firewall 是红帽系列7及以上的防火墙（如CentOS7.x），iptables是红帽系列6及以下（如CentOS6.x）的防火墙。</p><p>事实上，他们很可能同时安装在同一个系统上，并且相互作用影响！<br> 首先，iptables是最底层、最古老的防火墙系统，所有系统都会存在此防火墙，但一般而言只需保证该防火墙处于完全开放状态即可，其他不用管他，更不需要复杂的配置。而ufw和firewall都是较新linux系统上的替代iptables的工具，当他们同时安装在服务器上时，两者之间就会存在冲突。</p><p>24.1—firewall<br> sudo apt-get install firewalld -y<br> #使用方法<br> 　　1.查看所有开放的端口 (服务器已开放的端口)<br> 　　　　firewall-cmd --zone=public --list-ports<br> 　　　　firewall-cmd --list-ports<br> 　　2.查询是否开启80端口<br> 　　　　firewall-cmd --query-port=80/tcp<br> 　　3.开放端口<br> 　　　　3.1临时放行，服务器重启后失效<br> 　　　　　　firewall-cmd --zone=public --add-port=80/tcp<br> 　　　　3.2在public中放行，永久生效，服务器重启后不会失效<br> 　　　　　　firewall-cmd --zone=public --add-port=80/tcp --permanent<br> 　　　　3.3永久 放行连续的端口 1000-2000<br> 　　　　　　firewall-cmd --zone=public --add-port=1000-2000/tcp --permanent<br> 　　　　3.4永久放行不连续的端口 9000,9001<br> 　　　　　　firewall-cmd --zone=public --add-port=9000/tcp --add-port=9001/tcp --permanent<br> 　　4.删除端口<br> 　　　　4.1临时删除，服务器重启后自动添加<br> 　　　　　　firewall-cmd --zone=public --remove-port=80/tcp<br> 　　　　4.2在public中删除，永久生效，服务器重启后不会自动添加<br> 　　　　　　firewall-cmd --zone=public --remove-port=80/tcp --permanent<br> 　　　　4.3永久删除 连续的端口(1000-2000<br> 　　　　　　firewall-cmd --zone=public --remove-port=1000-2000/tcp --permanent<br> 　　　　4.4永久删除不连续的端口(9000,9001<br> 　　　　　　firewall-cmd --zone=public --remove-port=9000/tcp --remove-port=9001/tcp --permanent<br> 　　5.禁Ping设置规则<br> 　　　　5.1临时 禁Ping规则<br> 　　　　　　firewall-cmd --add-rich-rule=‘rule protocol value=icmp drop’<br> 　　　　5.2永久 禁Ping规则<br> 　　　　　　firewall-cmd --permanent --add-rich-rule=‘rule protocol value=icmp drop’<br> 　　　　5.3临时 删除禁Ping规则<br> 　　　　　　firewall-cmd --remove-rich-rule=‘rule protocol value=icmp drop’<br> 　　　　5.4永久 删除禁Ping规则<br> 　　　　　　firewall-cmd --permanent --remove-rich-rule=‘rule protocol value=icmp drop’<br> 　　6.http与https通讯<br> 　　　　6.1永久开放http<br> 　　　　　　firewall-cmd --permanent --add-service=http<br> 　　　　6.2永久允许http通信<br> 　　　　　　firewall-cmd --permanent --zone=public --add-service=http<br> 　　　　6.3永久允许https通信<br> 　　　　　　firewall-cmd --permanent --zone=public --add-service=https<br> 　　更新防火墙规则：firewall-cmd --reload</p><p>重启： systemctl restart firewalld</p><p>启动： systemctl start firewalld</p><p>状态： systemctl status firewalld</p><p>停止： systemctl disable firewalld</p><p>禁用： systemctl stop firewalld</p><p>开机启动：systemctl enable firewalld.service</p><p>开机禁用：systemctl disable firewalld.service</p><p>查看版本： firewall-cmd --version</p><p>查看帮助： firewall-cmd --help</p><p>显示状态： firewall-cmd --state</p><p>查看所有打开的端口： firewall-cmd --zone=public --list-ports</p><p>查看区域信息: firewall-cmd --get-active-zones</p><p>查看指定接口所属区域： firewall-cmd --get-zone-of-interface=eth0</p><p>拒绝所有包：firewall-cmd --panic-on</p><p>取消拒绝状态： firewall-cmd --panic-off</p><p>查看是否拒绝： firewall-cmd --query-panic</p><p>重新加载配置 (不管是添加或是删除端口都需要重新加载配置并重启firewall)</p><p>24.2—ufw<br> 1.启用<br> sudo ufw enable # 开启了防火墙，并在系统启动时自动开启<br> sudo ufw default deny # 关闭所有外部对本机的访问，但本机访问外部正常。<br> 2.关闭<br> sudo ufw disable<br> 3.查看状态<br> sudo ufw status<br> 4.<br> sudo ufw allow 80 # 允许外部访问80端口<br> sudo ufw delete allow 80 # 禁止外部访问80端口<br> sudo ufw allow from 192.168.1.1 # 允许此IP访问所有的本机端口<br> sudo ufw deny smtp # 禁止外部访问smtp服务<br> sudo ufw delete allow/deny smtp # 删除上面建立的smtp的规则，上面建立的规则为allow，这里就删除allow；为deny，这里就删除deny<br> sudo ufw deny proto tcp from 10.0.0.0/8 to 192.168.0.1 port 22 # 要拒绝所有的TCP流量从10.0.0.0/8 到 192.168.0.1地址的22端口</p><p>25.安装unzip</p><p>apt-get install unzip</p><p>#把文件解压到当前目录下<br> unzip file.zip</p><p>#把文件解压到指定的目录下，需要用到-d参数<br> unzip -d ./tmp/ file.zip</p><p>#解压的时候，有时候不想覆盖已经存在的文件，那么可以加上-n参数<br> unzip -n file.zip<br> unzip -n -d ./tmp/ file.zip</p><p>#只看一下zip压缩包中包含哪些文件，不进行解压缩<br> unzip -l file.zip</p><p>#查看显示的文件列表还包含压缩比率<br> unzip -v file.zip</p><p>#检查zip文件是否损坏<br> unzip -t file.zip</p><p>#将压缩文件file.zip在指定目录tmp下解压缩，如果已有相同的文件存在，要求unzip命令覆盖原先的文件<br> unzip -o file.zip -d ./tmp</p>',68)])])}const m=r(l,[["render",i]]);export{u as __pageData,m as default};
